    mockProton = {
      addEventListener: jest.fn(),
      removeEventListener: jest.fn(),
      // Mocking the events that are expected to be present in the proton object
      PROTON_UPDATE: 'PROTON_UPDATE',
      PROTON_UPDATE_AFTER: 'PROTON_UPDATE_AFTER',
      EMITTER_ADDED: 'EMITTER_ADDED',
      EMITTER_REMOVED: 'EMITTER_REMOVED',
      PARTICLE_CREATED: 'PARTICLE_CREATED',
      PARTICLE_UPDATE: 'PARTICLE_UPDATE',
      PARTICLE_DEAD: 'PARTICLE_DEAD',
    };

    baseRenderer = new BaseRenderer('element', 'stroke');
  });

  test('should set the parent property to the provided proton object', () => {
    baseRenderer.init(mockProton);
    expect(baseRenderer.parent).toBe(mockProton);
  });

  test('should register event listeners for proton events', () => {
    baseRenderer.init(mockProton);

    expect(mockProton.addEventListener).toHaveBeenCalledWith(
      mockProton.PROTON_UPDATE,
      expect.any(Function)
    );
    expect(mockProton.addEventListener).toHaveBeenCalledWith(
      mockProton.PROTON_UPDATE_AFTER,
      expect.any(Function)
    );
    expect(mockProton.addEventListener).toHaveBeenCalledWith(
      mockProton.EMITTER_ADDED,
      expect.any(Function)
    );
    expect(mockProton.addEventListener).toHaveBeenCalledWith(
      mockProton.EMITTER_REMOVED,
      expect.any(Function)
    );
    expect(mockProton.addEventListener).toHaveBeenCalledWith(
      mockProton.PARTICLE_CREATED,
      expect.any(Function)
    );
    expect(mockProton.addEventListener).toHaveBeenCalledWith(
      mockProton.PARTICLE_UPDATE,
      expect.any(Function)
    );
    expect(mockProton.addEventListener).toHaveBeenCalledWith(
      mockProton.PARTICLE_DEAD,
      expect.any(Function)
    );
  });

  test('should throw TypeError if proton is null or undefined', () => {
    expect(() => baseRenderer.init(null)).toThrow(TypeError);
    expect(() => baseRenderer.init(undefined)).toThrow(TypeError);
  });

  test('should throw TypeError if proton does not have addEventListener method', () => {
    const invalidProton = {};
    expect(() => baseRenderer.init(invalidProton)).toThrow(TypeError);
  });
});
